import { type RecordItem, type Profile, type Kind } from './domain';
// Demo previews may run over plain HTTP, where randomUUID is unavailable.
// getRandomValues remains available; real record IDs are generated by PostgreSQL.
export function demoId(){const bytes=crypto.getRandomValues(new Uint8Array(16));bytes[6]=(bytes[6]&15)|64;bytes[8]=(bytes[8]&63)|128;const s=Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('');return `${s.slice(0,8)}-${s.slice(8,12)}-${s.slice(12,16)}-${s.slice(16,20)}-${s.slice(20)}`;}
